#!/usr/bin/env bash
# One command for GO ERP preview.50: apply the reviewed live server fixes
# (each only from its exact known bytes, skipped when already applied), then
# prepare and publish the new desktop release through the reviewed rollout.
set -euo pipefail
test "$(id -u)" -eq 0
test "$(hostname -s)" = srv1836524
test "$#" -eq 1
go_release=$1
[[ "$go_release" =~ ^[a-f0-9]{40}$ ]]
echo "== 1/3 server fixes"
/usr/bin/python3 -I -B - "" <<'PY'
import base64,hashlib,json,os,shutil,sys,subprocess
root='/home/fasakha/public_html/'
for path,old,new,pairs in json.loads(base64.b64decode(sys.argv[1])):
    p=root+path;raw=open(p,'rb').read();digest=hashlib.sha256(raw).hexdigest()
    if digest==new:print('ALREADY_APPLIED',path);continue
    if digest!=old:print('FILE_CHANGED_STOP',path);sys.exit(3)
    out=raw
    for a,b in pairs:
        a,b=base64.b64decode(a),base64.b64decode(b)
        if out.count(a)!=1:print('ANCHOR_STOP',path);sys.exit(3)
        out=out.replace(a,b)
    if hashlib.sha256(out).hexdigest()!=new:print('RESULT_MISMATCH_STOP',path);sys.exit(3)
    backup='/root/'+os.path.basename(path)+'.before-release50'
    if not os.path.exists(backup):shutil.copy2(p,backup)
    st=os.stat(p);t=p+'.release50.tmp'
    with open(t,'wb') as f:f.write(out)
    os.chown(t,st.st_uid,st.st_gid);os.chmod(t,st.st_mode&0o7777);os.replace(t,p)
    if p.endswith('.php') and subprocess.run(['php','-l',p],capture_output=True).returncode!=0:
        shutil.copy2(backup,p);print('PHP_SYNTAX_STOP_RESTORED',path);sys.exit(3)
    print('APPLIED',path)
PY
echo "== 2/3 prepare preview.50"
curl -fsSL "https://raw.githubusercontent.com/omarmakramelbaz-hub/F-Backend/$go_release/deployment/run_go_erp_startup_window_root.sh" -o /root/run_go_erp_startup_window_root.sh
bash /root/run_go_erp_startup_window_root.sh "$go_release" --apply
echo "== 3/3 build, verify on Windows CI and publish preview.50 (up to 2 hours)"
bash /root/run_go_erp_startup_window_root.sh "$go_release" --complete
echo GO_ERP_RELEASE50_ALL_DONE
